188|export const executeDesignerMutation = async (
189|  binding: ResolvedEventBinding,
190|  bindingContext: Record<string, unknown>,
191|  body: Record<string, unknown>,
192|  callbacks: BindingMutationCallbacks = {},
193|): Promise<void> => {
194|  if (!binding.endpoint) {
195|    return;
196|  }
197|
198|  const url = resolveBindingUrl(binding.endpoint, bindingContext, binding.urlParams);
199|  const headers = {
200|    ...resolveBindingHeaders(bindingContext, binding.headers, binding.urlParams),
201|    'Content-Type': 'application/json',
202|  };
203|
204|  callbacks.onSubmittingChange?.(true);
205|  callbacks.onError?.(null);
206|
207|  try {
208|    const response = await designerFetch(url, {
209|      method: binding.actionType as DesignerBindingActionType,
210|      headers,
211|      body: JSON.stringify(body),
212|    });
213|
214|    if (!response.ok) {
215|      const message = await parseApiErrorMessage(response);
216|      callbacks.onError?.(message);
217|      callbacks.onLog?.({
218|        endpoint: url,
219|        method: binding.actionType,
220|        ok: false,
221|        status: response.status,
222|        errorMessage: message,
223|      });
224|      return;
225|    }
226|
227|    callbacks.onSuccess?.(response);
228|    callbacks.onLog?.({
229|      endpoint: url,
230|      method: binding.actionType,
231|      ok: true,
232|      status: response.status,
233|    });
234|  } catch (mutationFailure) {
235|    const message = mutationFailure instanceof Error ? mutationFailure.message : 'Request failed';
236|    callbacks.onError?.(message);
237|    callbacks.onLog?.({
238|      endpoint: binding.endpoint,
239|      method: binding.actionType,
240|      ok: false,
241|      errorMessage: message,
242|    });
243|  } finally {
244|    callbacks.onSubmittingChange?.(false);
245|  }
246|};
