248|const readRegionFormFieldValue = (field: Element): string => {
249|  if (field instanceof HTMLInputElement) {
250|    if (field.type === 'checkbox' || field.type === 'radio') {
251|      return field.checked ? 'true' : 'false';
252|    }
253|
254|    return field.value;
255|  }
256|
257|  if (field instanceof HTMLTextAreaElement || field instanceof HTMLSelectElement) {
258|    return field.value;
259|  }
260|
261|  const value = field.getAttribute('value');
262|  return value ?? '';
263|};
