265|export const collectRegionFormDataFromContainer = (
266|  container: ParentNode,
267|  formFieldNames: readonly string[],
268|): FormData => {
269|  const formData = new FormData();
270|
271|  for (const formFieldName of formFieldNames) {
272|    const escapedName = formFieldName.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
273|    const field = container.querySelector(`[name="${escapedName}"]`);
274|    if (!field) {
275|      continue;
276|    }
277|
278|    formData.set(formFieldName, readRegionFormFieldValue(field));
279|  }
280|
281|  return formData;
282|};
