306|export const resolveRegionDmlMethod = (
307|  regionData: Record<string, unknown> | null | undefined,
308|  primaryKey?: string,
309|): 'POST' | 'PUT' => {
310|  if (!primaryKey?.trim()) {
311|    return 'POST';
312|  }
313|
314|  const pkValue = regionData?.[primaryKey.trim()];
315|  if (pkValue === undefined || pkValue === null) {
316|    return 'POST';
317|  }
318|
319|  return String(pkValue).length > 0 ? 'PUT' : 'POST';
320|};
